real_logs = [f for f in glob.glob("logs/eval_*.jsonl") if "standin" not in f] + glob.glob("logs/server_real_*.jsonl")
calls = tok = n429 = 0
by = {}
for f in real_logs:
    for l in open(f, encoding="utf-8"):
        e = json.loads(l)
        if e["event"] == "send":
            calls += 1; by[e["model"]] = by.get(e["model"], 0) + 1
        if e["event"] == "last_token":
            tok += e["prompt_tokens"] + e["completion_tokens"]
        if e["event"] == "http_429":
            n429 += 1
probe = 0
for f in glob.glob("logs/groq_probe_*.jsonl"):
    probe += sum(1 for l in open(f) if '"status"' in l and '"tag": "models"' not in l)
print("pipeline real sends", calls, by, "| tokens (API usage) in real pipeline runs", tok, "| 429s", n429, "| probe requests", probe)
for tag in ("s_daily_known", "s_daily_learned"):
    for l in open(f"logs/server_{tag}.jsonl", encoding="utf-8"):
        e = json.loads(l)
        if e["event"] == "done" and e["status"] == "extractive_daily":
            print(tag, "\n", e["answer"][:1000]); break
for tag in ("s_burst_t10", "s_overload_t10", "real_burst"):
    for l in open(f"logs/server_{tag}.jsonl", encoding="utf-8"):
        e = json.loads(l)
        if e["event"] == "done" and e["status"] == "shed":
            print("SHED TEXT", tag, ":", e["answer"]); break

